-- Calpeda item load from 'Calpeda Data Entry (3_17_26).xlsx' into Lightspeed_test_fresh.
--
-- Replaces the Calpeda items wholesale (user decision, 2026-09-12): the 1,294 rows already
-- present matched NONE of the spreadsheet exactly - 176 were the same pump with the
-- voltage and impeller material truncated off the model, and 1,118 were unfilled
-- catalogue family placeholders like '(B-) NM 100/O (DN100 - DN125) KW HP' rather
-- than real sellable items.
--
-- Non-Calpeda items (No Brand, Acejet, Danfoss, Little Giant, Pentair Aurora,
-- Shinmaywa) are NOT touched.
--
-- item_code continues from MAX(item_code)+1 and never reuses a deleted code, which is
-- the rule generateItemCode() in item_service.go enforces: 'a gap or a concurrent
-- create never collides with, or reuses, an already-issued code'.

SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

DECLARE @brand_id bigint = (SELECT id FROM tbl_setup_item_brand WHERE code = 'CLP');
DECLARE @name_id  bigint = (SELECT id FROM tbl_setup_item_name  WHERE code = 'PMP');
DECLARE @class_id bigint = (SELECT id FROM tbl_setup_item_class WHERE code = 'PMP');
DECLARE @uom_id   bigint = (SELECT id FROM tbl_setup_item_unit_measurement WHERE code = 'UNIT');

IF @brand_id IS NULL OR @name_id IS NULL OR @class_id IS NULL OR @uom_id IS NULL
BEGIN
    RAISERROR('Setup rows missing: need brand CLP, name PMP, class PMP, uom UNIT.', 16, 1);
    ROLLBACK TRANSACTION; RETURN;
END

-- 1. Back the affected rows up before anything is removed.
SELECT * INTO zz_item_clp_backup_2026_09_12              FROM tbl_setup_item WHERE item_brand_id = @brand_id;
SELECT s.* INTO zz_item_clp_specs_backup_2026_09_12      FROM tbl_setup_item_additional_specs s
    JOIN tbl_setup_item i ON i.id = s.based_id WHERE i.item_brand_id = @brand_id;
SELECT x.* INTO zz_item_clp_inventory_backup_2026_09_12  FROM tbl_setup_item_inventory x
    JOIN tbl_setup_item i ON i.id = x.based_id WHERE i.item_brand_id = @brand_id;
SELECT x.* INTO zz_item_clp_image_backup_2026_09_12      FROM tbl_setup_item_image x
    JOIN tbl_setup_item i ON i.id = x.based_id WHERE i.item_brand_id = @brand_id;

DECLARE @backed int = (SELECT COUNT(*) FROM zz_item_clp_backup_2026_09_12);
PRINT 'backed up ' + CAST(@backed AS varchar(10)) + ' Calpeda items';

-- 2. Remove the old Calpeda rows, children first.
DECLARE @old TABLE (id bigint PRIMARY KEY);

DELETE FROM tbl_setup_item_additional_specs WHERE based_id IN (SELECT id FROM @old);
DELETE FROM tbl_setup_item_inventory        WHERE based_id IN (SELECT id FROM @old);
DELETE FROM tbl_setup_item_image            WHERE based_id IN (SELECT id FROM @old);
DELETE FROM tbl_item_trade_type             WHERE based_id IN (SELECT id FROM @old);
DELETE FROM tbl_bpi_items                   WHERE item_id  IN (SELECT id FROM @old);
DELETE FROM tbl_setup_item                  WHERE id       IN (SELECT id FROM @old);

PRINT 'deleted ' + CAST(@@ROWCOUNT AS varchar(10)) + ' Calpeda items';

-- 3. Load the spreadsheet. Codes continue from the highest ever issued.
DECLARE @next int = ISNULL((SELECT MAX(TRY_CAST(item_code AS INT)) FROM tbl_setup_item), 0) + 1;
DECLARE @new_id bigint;

VALUES (@name_id, @class_id, @brand_id, @uom_id, N'META SMALL  0.65KW 0.9HP 220V Stainless Steel 304 impeller', N'2025', RIGHT('0000' + CAST(@next AS varchar(10)), 4), N'TANGIBLE', 0, 0);
SET @new_id = SCOPE_IDENTITY(); SET @next = @next + 1;

VALUES (@name_id, @class_id, @brand_id, @uom_id, N'META  1.35KW 1.8HP 220V Stainless Steel 304 impeller', N'2025', RIGHT('0000' + CAST(@next AS varchar(10)), 4), N'TANGIBLE', 0, 0);
