DECLARE @loaded int = (SELECT COUNT(*) FROM tbl_setup_item WHERE item_brand_id = @brand_id);
PRINT 'loaded ' + CAST(@loaded AS varchar(10)) + ' Calpeda items';

COMMIT TRANSACTION;

-- Verification
SELECT 'calpeda items'   AS metric, COUNT(*) AS value FROM tbl_setup_item i JOIN tbl_setup_item_brand b ON b.id=i.item_brand_id WHERE b.code='CLP'
UNION ALL SELECT 'distinct models', COUNT(DISTINCT item_model) FROM tbl_setup_item i JOIN tbl_setup_item_brand b ON b.id=i.item_brand_id WHERE b.code='CLP'
UNION ALL SELECT 'with long desc',  COUNT(*) FROM tbl_setup_item_additional_specs s JOIN tbl_setup_item i ON i.id=s.based_id JOIN tbl_setup_item_brand b ON b.id=i.item_brand_id WHERE b.code='CLP' AND ISNULL(s.long_description,'')<>''
UNION ALL SELECT 'with trade type', COUNT(*) FROM tbl_item_trade_type t JOIN tbl_setup_item i ON i.id=t.based_id JOIN tbl_setup_item_brand b ON b.id=i.item_brand_id WHERE b.code='CLP'
UNION ALL SELECT 'duplicate codes', COUNT(*) FROM (SELECT item_code FROM tbl_setup_item GROUP BY item_code HAVING COUNT(*)>1) d
UNION ALL SELECT 'total items',     COUNT(*) FROM tbl_setup_item;